#!/usr/bin/env node

/**
 * Braille -> Base64 -> ROT cipher decoder
 *
 * Braille 6-dot cell layout:
 *   1 4
 *   2 5
 *   3 6
 *
 * Bit string order: dot1, dot2, dot3, dot4, dot5, dot6
 */

const fs = require("fs");

// --- Braille bit-string data ---
const data =
  "";

// --- Step 1: Build braille lookup tables ---

/**
 * Convert an array of dot numbers (1-6) to a 6-bit string.
 * Bit positions map directly: index 0 = dot 1, index 5 = dot 6.
 */
function dotsToBits(dots) {
  const bits = ["0", "0", "0", "0", "0", "0"];
  for (const d of dots) {
    bits[d - 1] = "1";
  }
  return bits.join("");
}

// First decade: letters a-j
const firstDecade = [
  { char: "a", dots: [1] },
  { char: "b", dots: [1, 2] },
  { char: "c", dots: [1, 4] },
  { char: "d", dots: [1, 4, 5] },
  { char: "e", dots: [1, 5] },
  { char: "f", dots: [1, 2, 4] },
  { char: "g", dots: [1, 2, 4, 5] },
  { char: "h", dots: [1, 2, 5] },
  { char: "i", dots: [2, 4] },
  { char: "j", dots: [2, 4, 5] },
];

// Second decade: letters k-t (first decade + dot 3)
const secondDecade = [
  { char: "k", dots: [1, 3] },
  { char: "l", dots: [1, 2, 3] },
  { char: "m", dots: [1, 3, 4] },
  { char: "n", dots: [1, 3, 4, 5] },
  { char: "o", dots: [1, 3, 5] },
  { char: "p", dots: [1, 2, 3, 4] },
  { char: "q", dots: [1, 2, 3, 4, 5] },
  { char: "r", dots: [1, 2, 3, 5] },
  { char: "s", dots: [2, 3, 4] },
  { char: "t", dots: [2, 3, 4, 5] },
];

// Third decade: letters u-z (second decade + dot 6, except w)
const thirdDecade = [
  { char: "u", dots: [1, 3, 6] },
  { char: "v", dots: [1, 2, 3, 6] },
  { char: "w", dots: [2, 4, 5, 6] },
  { char: "x", dots: [1, 3, 4, 6] },
  { char: "y", dots: [1, 3, 4, 5, 6] },
  { char: "z", dots: [1, 3, 5, 6] },
];

// Build letter lookup: bits -> lowercase letter
const letterMap = {};
for (const group of [firstDecade, secondDecade, thirdDecade]) {
  for (const { char, dots } of group) {
    letterMap[dotsToBits(dots)] = char;
  }
}

// Number patterns: after a number sign, a-j patterns map to 1-9, 0
const numberMap = {};
firstDecade.forEach(({ dots }, index) => {
  const digit = String((index + 1) % 10); // a=1, b=2, ... j=0
  numberMap[dotsToBits(dots)] = digit;
});

// Special indicators
const CAPITAL_SIGN = dotsToBits([6]); // 000001
const NUMBER_SIGN = dotsToBits([3, 4, 5, 6]); // 001111
const SPACE = "000000";

// Punctuation that may appear in base64 context
const punctuationMap = {
  [dotsToBits([2, 3, 5])]: "+", // dots 2,3,5
  [dotsToBits([3, 4])]: "/", // dots 3,4
  [dotsToBits([2, 3, 5, 6])]: "=", // dots 2,3,5,6
};

// --- Step 1: Decode braille ---

function decodeBraille(bitstring) {
  const cells = [];
  for (let i = 0; i < bitstring.length; i += 6) {
    cells.push(bitstring.slice(i, i + 6));
  }

  const result = [];
  let i = 0;
  while (i < cells.length) {
    const cell = cells[i];

    if (cell === SPACE) {
      result.push(" ");
      i++;
    } else if (cell === CAPITAL_SIGN) {
      // Next cell is an uppercase letter
      i++;
      if (i < cells.length) {
        const nextCell = cells[i];
        if (letterMap[nextCell]) {
          result.push(letterMap[nextCell].toUpperCase());
        } else {
          result.push(`[CAP+${nextCell}]`);
        }
        i++;
      }
    } else if (cell === NUMBER_SIGN) {
      // Number sign applies to the next single cell only
      i++;
      if (i < cells.length && numberMap[cells[i]]) {
        result.push(numberMap[cells[i]]);
        i++;
      }
    } else if (letterMap[cell]) {
      result.push(letterMap[cell]);
      i++;
    } else if (punctuationMap[cell]) {
      result.push(punctuationMap[cell]);
      i++;
    } else {
      const dots = [];
      for (let b = 0; b < 6; b++) {
        if (cell[b] === "1") dots.push(b + 1);
      }
      result.push(`[?dots:${dots.join(",")}]`);
      i++;
    }
  }

  return result.join("");
}

// --- Step 2: Base64 decode ---

function decodeBase64(str) {
  return Buffer.from(str, "base64").toString("utf-8");
}

// --- Step 3: ROT cipher decode ---

function rotDecode(text, shift) {
  return text
    .split("")
    .map((ch) => {
      if (/[a-z]/.test(ch)) {
        return String.fromCharCode(
          ((ch.charCodeAt(0) - 97 + shift) % 26) + 97,
        );
      }
      if (/[A-Z]/.test(ch)) {
        return String.fromCharCode(
          ((ch.charCodeAt(0) - 65 + shift) % 26) + 65,
        );
      }
      return ch;
    })
    .join("");
}

function findRotShift(text) {
  // Count letter frequencies
  const freq = {};
  for (const ch of text.toLowerCase()) {
    if (/[a-z]/.test(ch)) {
      freq[ch] = (freq[ch] || 0) + 1;
    }
  }

  // Find the most common letter
  let mostCommon = "a";
  let maxCount = 0;
  for (const [letter, count] of Object.entries(freq)) {
    if (count > maxCount) {
      maxCount = count;
      mostCommon = letter;
    }
  }

  // The most common letter in English is 'e', so shift = e - mostCommon
  const shift = (101 - mostCommon.charCodeAt(0) + 26) % 26; // 101 = 'e'
  return { shift, mostCommon };
}

// --- Main execution ---

console.log("=== Step 1: Braille Decoding ===");
const brailleDecoded = decodeBraille(data);
console.log(brailleDecoded);
console.log();

// Check for any unknown patterns
if (brailleDecoded.includes("[?")) {
  console.log("WARNING: Unknown braille patterns detected!");
  console.log();
}

console.log("=== Step 2: Base64 Decoding ===");
const base64String = brailleDecoded.replace(/ /g, "");
let plaintext;
try {
  plaintext = decodeBase64(base64String);
  console.log(plaintext);
  console.log();
} catch (e) {
  console.error("Base64 decode failed:", e.message);
  process.exit(1);
}

console.log("=== Step 3: ROT Cipher Decoding ===");
const { shift, mostCommon } = findRotShift(plaintext);
console.log(`Most common letter: '${mostCommon}'`);
console.log(`ROT shift needed: ${shift} (ROT${shift})`);
console.log();

const finalText = rotDecode(plaintext, shift);
console.log("=== Final Decoded Text ===");
console.log(finalText);

// Write output
fs.writeFileSync("output.md", finalText, "utf-8");
console.log("\nResult written to output.md");
